<script setup>
import { tr, dateTime } from '../i18n/index.js';

import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';
import {ElMessageBox} from 'element-plus';
import {isResolved} from '../utils/health';
import {api} from '../api/client';
const props=defineProps({active:{type:Boolean,default:true},mappings:{type:Array,default:()=>[]}});
const view=ref({events:[],incidents:[]}),error=ref(''),busy=ref(false),enabled=ref(false),webhook=ref(''),token=ref(''),maintenance=ref('keep');
let controller,disposed=false,initialized=false,loadVersion=0,baselineEnabled=false;
const saving=ref(false),configRevision=ref('');
function acceptView(data){const pristine=!initialized||(enabled.value===baselineEnabled&&!webhook.value&&!token.value&&maintenance.value==='keep');view.value=data;if(pristine){enabled.value=!!data.enabled;baselineEnabled=!!data.enabled;configRevision.value=data.revision||'';initialized=true}}
async function load(){if(!props.active||document.hidden)return;if(busy.value||saving.value)return;busy.value=true;const version=++loadVersion;controller=new AbortController();try{const data=await api.operations(controller.signal);if(!disposed&&version===loadVersion){acceptView(data);error.value=data.revision&&configRevision.value&&data.revision!==configRevision.value?tr("通知配置已更新，请重新加载后编辑"):''}}catch(e){if(!disposed&&version===loadVersion&&e.name!=='AbortError')error.value=e.message}finally{if(!disposed&&version===loadVersion)busy.value=false}}
async function save(){if(saving.value||!initialized)return;saving.value=true;loadVersion++;controller?.abort();busy.value=false;try{let until=view.value.maintenance_until;if(maintenance.value==='off')until=new Date(0).toISOString();if(maintenance.value==='hour')until=new Date(Date.now()+3600000).toISOString();if(maintenance.value==='day')until=new Date(Date.now()+86400000).toISOString();const data=await api.saveNotifications({enabled:enabled.value,webhook:webhook.value,token:token.value,revision:configRevision.value,maintenance_until:until||new Date(0).toISOString()});if(!disposed){webhook.value='';token.value='';maintenance.value='keep';initialized=false;acceptView(data);error.value=''}}catch(e){if(!disposed)error.value=e.message}finally{if(!disposed)saving.value=false}}
async function reloadConfig(){if(saving.value)return;try{await ElMessageBox.confirm(tr("重新加载会放弃未保存的通知配置。"),tr("重新加载配置"),{get confirmButtonText() { return tr("重新加载"); },get cancelButtonText() { return tr("返回编辑"); }});if(disposed)return;loadVersion++;controller?.abort();busy.value=false;webhook.value='';token.value='';maintenance.value='keep';initialized=false;await load()}catch(e){if(e!=='cancel'&&e!=='close'&&!disposed)error.value=e.message}}
const recent=computed(()=>[...(view.value.events||[])].reverse().slice(0,30));
const incidents=computed(()=>[...(view.value.incidents||[])].sort((a,b)=>Number(isResolved(a))-Number(isResolved(b))||new Date(b.started)-new Date(a.started)).slice(0,20));
const labels={get 'duplicate-session'() { return tr("同账号重复拨号 · 请检查地址冲突"); },get 'shared-upstream'() { return tr("多节点同时异常 · 公共链路待核验"); },get 'local-unstable'() { return tr("本地转发异常"); },get 'local-recovering'() { return tr("恢复中"); },get 'local-circuit-open'() { return tr("自动恢复冷却"); },get 'upstream'() { return tr("节点转发异常"); },get 'dns'() { return tr("DNS 异常"); },get 'unknown'() { return tr("检测数据过期或尚未采集"); }};
const eventLabels={get 'incident-ended'() { return tr("监测结束"); },get 'incident-changed'() { return tr("故障分类变化"); },get 'session-limit'() { return tr("PPP 会话上限"); },get 'rule-repair'() { return tr("规则修复"); },get 'process-recovery'() { return tr("进程恢复"); },get 'incident-open'() { return tr("故障开始"); },get 'incident-recovered'() { return tr("故障结束"); },get 'ppp-up'() { return tr("拨号上线"); },get 'ppp-down'() { return tr("拨号下线"); },get 'operation'() { return tr("管理操作"); },get 'session-disconnect'() { return tr("断开会话"); },get 'connection-close'() { return tr("关闭连接"); }};
function time(t){return t&&!t.startsWith('0001')?dateTime(t):'—'}
const connectionMap=ref(''),connectionRows=ref([]),connectionError=ref(''),connectionBusy=ref(false),connectionShown=ref(false),truncated=ref(false);
let connectionController,connectionVersion=0;
function closeConnections(){connectionVersion++;connectionController?.abort();connectionShown.value=false;connectionBusy.value=false;connectionRows.value=[]}
async function connections(id){closeConnections();connectionMap.value=id;connectionShown.value=true;connectionBusy.value=true;connectionError.value='';const version=connectionVersion;connectionController=new AbortController();try{const d=await api.connections(id,connectionController.signal);if(version===connectionVersion&&!disposed){connectionRows.value=d.rows||[];truncated.value=d.truncated}}catch(e){if(version===connectionVersion&&!disposed&&e.name!=='AbortError')connectionError.value=e.message}finally{if(version===connectionVersion&&!disposed)connectionBusy.value=false}}
const closingConnection=ref('');
async function endConnection(row){if(closingConnection.value)return;const mapping=connectionMap.value,version=connectionVersion;try{await ElMessageBox.confirm(tr("关闭此连接？应用可能重新建立连接。"),tr("连接管理"),{type:'warning'});if(disposed||version!==connectionVersion||!connectionShown.value)return;closingConnection.value=row.id;await api.closeConnection(mapping,row.id);if(!disposed&&version===connectionVersion)await connections(mapping)}catch(e){if(!disposed&&version===connectionVersion&&e!=='cancel'&&e!=='close')connectionError.value=e.message}finally{closingConnection.value=''}}

watch(()=>props.active,active=>{if(active)load()});onMounted(load);const timer=setInterval(()=>{if(!document.hidden)load()},30000);onBeforeUnmount(()=>{disposed=true;controller?.abort();closeConnections();clearInterval(timer)});
</script>
<template>
<el-card shadow="never" class="section-gap operations-panel"><template #header>{{ tr("故障事件与操作记录") }}</template>
<el-alert v-if="error||view.warning" :title="error||view.warning" type="warning" :closable="false"/>
<el-button :loading="busy" @click="load">{{ tr("刷新事件") }}</el-button>
<p v-if="!incidents.length" class="muted">{{ tr("暂无故障事件") }}</p>
<article v-for="row in incidents" :key="row.key+row.started" class="operation-row"><strong>{{labels[row.state]||row.state}} · {{isResolved(row)?tr("已结束"):tr("处理中")}}</strong><p>{{row.scope==='node'?tr("节点关联"):row.scope==='server-suspected'?tr("公共故障关联"):tr("映射")}} · {{row.affected.join('、')}}</p><p>{{time(row.started)}} → {{time(row.resolved)}}</p></article>
<el-collapse><el-collapse-item :title='tr("最近操作与拨号事件")' name="events"><article v-for="row in recent" :key="row.id" class="operation-row"><strong>{{eventLabels[row.kind]||row.kind}} · {{row.resource}}</strong><p>{{time(row.at)}} · {{row.detail}}</p></article><p v-if="!recent.length" class="muted">{{ tr("暂无记录") }}</p></el-collapse-item>
<el-collapse-item :title='tr("故障通知")' name="notifications"><el-form label-position="top" :disabled="saving||!initialized"><el-form-item :label='tr("通知开关")'><el-switch v-model="enabled"/></el-form-item><el-form-item label="HTTPS Webhook"><el-input v-model="webhook" :placeholder='tr("留空保留原地址")' autocomplete="off"/></el-form-item><el-form-item label="Bearer Token"><el-input v-model="token" type="password" show-password :placeholder='tr("更换地址时请重新填写令牌")' autocomplete="new-password"/></el-form-item><el-form-item :label='tr("维护静默")'><el-select v-model="maintenance"><el-option value="keep" :label='tr("保留当前设置")'/><el-option value="off" :label='tr("结束静默")'/><el-option value="hour" :label='tr("静默 1 小时")'/><el-option value="day" :label='tr("静默 24 小时")'/></el-select></el-form-item><p class="muted">{{ tr("已配置：") }}{{view.configured?tr("是"):tr("否")}} · {{view.delivery||tr("暂无发送记录")}} {{ tr("· 静默至") }} {{time(view.maintenance_until)}}</p><el-button :loading="saving" :disabled="!initialized" @click="save">{{ tr("保存通知设置") }}</el-button><el-button :disabled="saving" @click="reloadConfig">{{ tr("重新加载配置") }}</el-button></el-form></el-collapse-item></el-collapse>
</el-card>
<el-card shadow="never" class="section-gap"><template #header>{{ tr("映射连接") }}</template><div class="connection-controls"><el-button v-for="m in mappings.filter(m=>m.status==='running'&&m.observe_connections)" :key="m.id" @click="connections(m.id)">{{m.tun_name}} {{ tr("· 查看连接") }}</el-button></div><p class="muted">{{ tr("按需读取，最多显示 500 条；目标信息不写入历史。") }}</p></el-card>
<el-dialog v-model="connectionShown" :title='tr("当前连接")' width="min(760px, calc(100vw - 24px))" append-to-body class="connections-dialog" @close="closeConnections"><el-alert v-if="connectionError" :title="connectionError" type="warning" :closable="false"/><p v-if="connectionBusy">{{ tr("读取中…") }}</p><p v-else-if="!connectionRows.length&&!connectionError">{{ tr("暂无连接") }}</p><p v-if="truncated">{{ tr("连接较多，仅展示前 500 条。") }}</p><article v-for="row in connectionRows" :key="row.id" class="operation-row"><strong>{{row.metadata.host||row.metadata.destinationIP}}:{{row.metadata.destinationPort}}</strong><p>{{row.metadata.network}} {{ tr("· 建立于") }} {{time(row.start)}}</p><p>{{ tr("上传") }} {{row.upload}} {{ tr("B · 下载") }} {{row.download}} B</p><el-button :disabled="!!closingConnection" :loading="closingConnection===row.id" @click="endConnection(row)">{{ tr("关闭连接") }}</el-button></article></el-dialog>
</template>
<style scoped>.operation-row{overflow-wrap:anywhere;padding:12px 0;border-bottom:1px solid var(--el-border-color-lighter)}.operation-row p{margin:7px 0;font-size:14px}.connection-controls{display:flex;flex-wrap:wrap;gap:8px}.connection-controls .el-button{margin:0}.operations-panel .el-form{max-width:620px}</style>
